"""One exact arithmetic sweep of the frozen UPS auxiliary breakeven model."""
from datetime import datetime, timezone
from decimal import Decimal
from fractions import Fraction as F
from hashlib import sha256
from itertools import product
import json
import os
from pathlib import Path
import socket
import sys


def sha(raw):
    return sha256(raw).hexdigest()


def now():
    return datetime.now(timezone.utc).isoformat()


def need(ok,message):
    if not ok:
        raise ValueError(message)


def write(path,row):
    with path.open('x',encoding='utf-8',newline='\n') as stream:
        json.dump(row,stream,ensure_ascii=True,indent=2,allow_nan=False)
        stream.write('\n')
        stream.flush()
        os.fsync(stream.fileno())


def label(values):
    return 'LOSE' if min(values)<0 else 'TIE' if min(values)==0 else 'WIN'


def region(coeffs, unavailable=None):
    if unavailable:
        return {unavailable:['[0,1]']}
    cuts=sorted({F(0),F(1)}|{-a/b for a,b in coeffs if b and 0<=-a/b<=1})
    at=lambda p:label([a+b*p for a,b in coeffs])
    pieces=[]
    def add(lo,hi,left,right,status):
        if pieces and pieces[-1][4]==status and pieces[-1][1]==lo and (pieces[-1][3] or left):
            pieces[-1][1]=hi
            pieces[-1][3]=right
        else:
            pieces.append([lo,hi,left,right,status])
    for i,p in enumerate(cuts):
        if i:
            prev=cuts[i-1]
            add(prev,p,False,False,at((p+prev)/2))
        add(p,p,True,True,at(p))
    result={}
    for lo,hi,left,right,status in pieces:
        span='{'+str(lo)+'}' if lo==hi else ('[' if left else '(')+str(lo)+','+str(hi)+(']' if right else ')')
        result.setdefault(status,[]).append(span)
    return result


def solve(params,grid):
    z={k:(v if isinstance(v,bool) else F(v)) for k,v in params.items()}
    u0,u1=z['unresolved_off'],z['unresolved_on']
    a,b=(1-u0)*z['sensitivity'],(1-u1)*(1-z['specificity'])
    q,k=z['success'],z['check_charge_over_gap']
    available={'defer':True,'escalate':z['escalate_person_over_cap']<=1,
        'direct':z['direct_authorized'] and z['direct_time_over_deadline']<1 and z['restore_person_over_cap']<=1}
    timely=z['direct_time_over_deadline']+z['check_extra_time_over_deadline']<1
    gate=z['inspection_branch_authorized'] and timely
    worst=z['inspect_person_over_cap']+(z['restore_person_over_cap'] if gate else 0)
    inspect_eligible=worst<=1
    ri=a*q if gate else F(0)
    di=b*z['false_positive_downtime_over_gap'] if gate else F(0)
    r={'defer':F(0),'escalate':q*z['escalation_timely_reach'],'direct':q}
    d={'defer':F(0),'escalate':F(0),'direct':z['direct_downtime_over_gap']}
    coeff={}
    for action in r:
        c0=d[action]-di
        c1=ri-r[action]
        coeff[action]=(c0-k,c1-c0)
    legal=[x for x in r if available[x]]
    def unavailable(action):
        if action!='all' and not available[action]:
            return 'COMPARATOR_INELIGIBLE'
        return None if inspect_eligible else 'INSPECTION_OVER_PERSON_TIME_CAP'
    def branch_sums(p):
        # Unit gap leaves: off=1, on=0. Failure and no timely attempt keep the original leaf.
        off_reports=[a,1-u0-a,u0]
        on_reports=[b,1-u1-b,u1]
        need(sum(off_reports)==sum(on_reports)==1 and min(off_reports+on_reports)>=0,'Invalid observation masses')
        off_inspect=off_reports[0]*(1-(q if gate else 0))+sum(off_reports[1:])
        on_inspect=on_reports[0]*(z['false_positive_downtime_over_gap'] if gate else 0)
        inspect=p*off_inspect+(1-p)*on_inspect+k
        return {x:p*(1-r[x])+(1-p)*d[x]-inspect for x in r}
    groups={x:[coeff[x]] for x in r}
    groups['all']=[coeff[x] for x in legal]
    tables={x:dict(regions=region(cs,unavailable(x)),grid_counts={}) for x,cs in groups.items()}
    for p in grid:
        sums=branch_sums(p)
        need(all(sums[x]==coeff[x][0]+p*coeff[x][1] for x in r),'Leaf sums disagree with the boundary')
        for action,record in tables.items():
            mark=unavailable(action) or label([sums[x] for x in legal] if action=='all' else [sums[action]])
            counts=record['grid_counts']
            counts[mark]=counts.get(mark,0)+1
    for x in r:
        tables[x]['advantage_over_gap_at_p0']=str(coeff[x][0])
        tables[x]['advantage_over_gap_slope']=str(coeff[x][1])
    return dict(positive_if_off=str(a),positive_if_on=str(b),timely=timely,authorized_and_timely=gate,
        conditional_success_over_off=dict(inspect=str(ri),**{x:str(v) for x,v in r.items()}),
        active_disturbance_over_gap=dict(inspect=str(di),**{x:str(v) for x,v in d.items()}),
        eligible_no_inspection=legal,inspection_eligible=inspect_eligible,
        inspection_worst_person_over_cap=str(worst),
        expected_inspect_person_over_cap_at_p0=str(z['inspect_person_over_cap']+(b*z['restore_person_over_cap'] if gate else 0)),
        expected_inspect_person_over_cap_slope=str((a-b)*z['restore_person_over_cap'] if gate else 0),
        comparisons=tables)


def run(spec,raw):
    b1=json.loads(raw,parse_float=Decimal)
    need(b1['status']=='COMPLETED_PAIRED_PROBE','Use the completed B1 matched probe')
    leaves={}
    for asset in spec['asset_ids']:
        times={}
        for name,case in b1['cases'].items():
            need([case['applied_outage_s'],case['end_s']]==spec['window_s'],'B1 outage or window differs')
            times[case['ups_in_service']]=F(case['auxiliary_power_interruption'][asset]['zero_power_s'])
        gap=times[0]-times[1]
        need(gap>0,'B1 does not have a positive gap for '+asset)
        leaves[asset]=dict(off_s=str(times[0]),on_s=str(times[1]),gap_s=str(gap),
            boundary_mapping='same normalized p regions; multiply normalized advantage/charge by this asset gap')
    steps=spec['p_grid_divisions'];grid=[F(i,steps) for i in range(steps+1)]
    rows=[]
    for regime,override in spec['direct_regimes'].items():
        for q,k in product(spec['success_grid'],spec['charge_grid']):
            delta=dict(override,success=q,check_charge_over_gap=k)
            rows.append(dict(kind='crossed_success_charge',regime=regime,parameters=delta,
                **solve(dict(spec['reference'],**delta),grid)))
    for parameter,values in spec['one_factor_sweeps'].items():
        for v in values:
            delta={parameter:v}
            rows.append(dict(kind='one_factor',regime='disruptive_direct',parameters=delta,
                **solve(dict(spec['reference'],**delta),grid)))
    return dict(leaves_by_asset=leaves,p_grid=dict(start=0,end=1,divisions=steps),
        parameter_rows=rows,arithmetic_checks=dict(exact_branch_sum_matches_boundary_at_grid_points=True,
            rows=len(rows),prior_points_per_row=len(grid),row_prior_evaluations=len(rows)*len(grid)))


def main():
    path,out=(Path(p).resolve() for p in sys.argv[1:])
    frozen=path.read_bytes();spec=json.loads(frozen);runner=Path(__file__).read_bytes()
    root=Path('/root/private_data')
    need(os.name=='posix' and os.geteuid()==0 and root.is_mount() and out.is_relative_to(root),'Use approved private CPU storage')
    need(socket.gethostname()==spec['host'] and sys.version.split()[0]==spec['python'],'Remote runtime differs')
    need(sha(runner)==spec['runner_sha256'],'Frozen runner differs')
    out.mkdir(mode=0o700,exist_ok=False);start=now()
    write(out/'started.json',dict(utc=start,attempt=1,spec_sha256=sha(frozen)))
    result=dict(schema='aegisdc-39r-ups-a1-stage2-breakeven-result-v1',status='FAILED',
        classification='DECLARED_SYNTHETIC_BOUNDARIES_NOT_FIELD_ESTIMATES',started_utc=start,freeze_id=spec['id'],
        frozen_spec_sha256=sha(frozen),frozen_spec=spec,runner_sha256=sha(runner),runner_source=runner.decode(),
        private_originals=str(out.parent),command='python -B runner.py freeze.json ../capture',
        accounting=dict(arithmetic_attempts=1,facility_entries=0,policy_calls=0,model_calls=0,registered_research_runs=0))
    try:
        original=Path(spec['b1']['remote_path']);raw=original.read_bytes()
        need(sha(raw)==spec['b1']['sha256'],'B1 frozen original differs')
        result['analysis']=run(spec,raw)
        need(path.read_bytes()==frozen and sha(original.read_bytes())==spec['b1']['sha256'],'Frozen input changed')
        result['status']='COMPLETED_BREAKEVEN_SWEEP'
    except BaseException as error:
        result['error']=dict(type=type(error).__name__,message=str(error))
        raise
    finally:
        result['finished_utc']=now();write(out/'result.json',result)
        print(json.dumps(dict(status=result['status'],result_sha256=sha((out/'result.json').read_bytes()),
            rows=result.get('analysis',{}).get('arithmetic_checks')),separators=(',',':')),flush=True)


if __name__=='__main__':
    main()
